import os, socket, ssl
print('PROXY_ENV=' + os.environ.get('HTTPS_PROXY', 'unset'))
try:
    print('RESOLVED=' + socket.gethostbyname('one.one.one.one'))
except OSError as e:
    print('RESOLVED=ERROR', e)
def tls(name):
    try:
        with socket.create_connection(('one.one.one.one', 8443), timeout=10) as s:
            with ssl.create_default_context().wrap_socket(s, server_hostname=name):
                return 'VERIFIED'
    except OSError as e:
        return 'ERROR ' + str(e)
print('TLS_PROXY=' + tls('one.one.one.one'))
print('TLS_OTHER_NAME=' + tls('dns.google'))
try:
    socket.create_connection(('1.1.1.1', 443), timeout=5).close()
    print('DIRECT=REACHED')
except OSError:
    print('DIRECT=BLOCKED')
EOF
